#pragma once
#include "runtime/runtime.hpp"
#include <cuda_runtime_api.h>
#include <infini/rt/device_guard.h>
#include <array>
#include <atomic>
#include <chrono>
#include <ctime>
#include <stdexcept>
#include <nlohmann/json.hpp>
namespace deep_owner_r8900 {
using RT=infinilm::runtime::Runtime;
inline double wall(){return std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();}
inline double cpu(){timespec t{};if(clock_gettime(CLOCK_THREAD_CPUTIME_ID,&t))throw std::runtime_error("owner clock");return t.tv_sec+t.tv_nsec*1e-9;}
inline void ok(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
struct Layer{RT*owner=nullptr;const void*decoder=nullptr;void*stream=nullptr;std::array<cudaEvent_t,32>ev{};std::array<double,32>hw{},tc{},gpu{};unsigned seen=0;bool done=false;double drain=0;int create_before=-1,create_during=-1,query_before=-1,query_during=-1;};
inline std::array<std::array<Layer,43>,8>pool{};
inline std::atomic<int>window{0};
inline thread_local Layer*active=nullptr;
inline void initialize(RT&r,const void*self,size_t layer){r.assertOwnerThread();if(layer>=43||r.device().index()<0||r.device().index()>=8)throw std::logic_error("owner layer/device");auto&p=pool.at(r.device().index()).at(layer);if(p.owner)throw std::logic_error("duplicate decoder owner");p.owner=&r;p.decoder=self;p.stream=r.stream();ok(cudaGetDevice(&p.create_before));infini::rt::DeviceGuard device_scope(r.device().type(),r.device().index(),true);ok(cudaGetDevice(&p.create_during));if(p.create_during!=r.device().index())throw std::logic_error("event create current device");for(auto&e:p.ev)ok(cudaEventCreate(&e));}
inline void mark(RT&r,int id){if(!active)return;r.assertOwnerThread();infini::rt::DeviceGuard device_scope(r.device().type(),r.device().index(),true);int current=-1;ok(cudaGetDevice(&current));if(current!=r.device().index())throw std::logic_error("event mark current device");auto&p=*active;if(p.owner!=&r||p.stream!=r.stream()||id<0||id>=32||(p.seen&(1u<<id)))throw std::logic_error("owner event binding/overflow/order");p.hw[id]=wall();p.tc[id]=cpu();ok(cudaEventRecord(p.ev[id],static_cast<cudaStream_t>(r.stream())));p.seen|=1u<<id;}
struct Span{RT&r;int id;bool open;Span(RT&rr,int k):r(rr),id(k),open(active){if(open)mark(r,2*id);}void close(){if(open){mark(r,2*id+1);open=false;}}~Span()noexcept(false){if(open&&std::uncaught_exceptions()==0)close();}};
struct Context{RT&r;Layer*previous;bool enabled=false;Context(RT&rr,const void*self):r(rr),previous(active){if(!window.load())return;r.assertOwnerThread();for(auto&p:pool.at(r.device().index()))if(p.decoder==self){if(p.owner!=&r||p.stream!=r.stream()||p.seen||p.done)throw std::logic_error("owner active context");active=&p;enabled=true;mark(r,0);return;}throw std::logic_error("unknown decoder layer");}void beforeDrain(){if(enabled)mark(r,1);}void afterDrain(double start){if(!enabled)return;auto&p=*active;p.drain=wall()-start;ok(cudaGetDevice(&p.query_before));infini::rt::DeviceGuard device_scope(r.device().type(),r.device().index(),true);ok(cudaGetDevice(&p.query_during));if(p.query_during!=r.device().index())throw std::logic_error("event query current device");if(p.seen!=0xffffffffu)throw std::logic_error("missing owner markers");for(int i=0;i<32;++i){ok(cudaEventQuery(p.ev[i]));float ms=0;ok(cudaEventElapsedTime(&ms,p.ev[0],p.ev[i]));p.gpu[i]=ms;}for(int k=0;k<16;++k)if(p.hw[2*k+1]<p.hw[2*k]||p.tc[2*k+1]<p.tc[2*k])throw std::logic_error("host order");p.done=true;}~Context(){active=previous;}};
inline int arm(int w){if(w<0||w>2||window.load())return 1;if(!w)return 0;for(auto&rank:pool)for(auto&p:rank){if(!p.owner)return 2;if(p.seen&&!p.done)return 3;}for(auto&rank:pool)for(auto&p:rank){p.seen=0;p.done=false;}window.store(w);return 0;}
inline std::string read(){int w=window.load();if(!w)throw std::logic_error("owner read without arm");nlohmann::json rows=nlohmann::json::array();for(int dev=0;dev<8;++dev)for(int l=0;l<43;++l){auto&p=pool[dev][l];if(!p.done||p.seen!=0xffffffffu)throw std::logic_error("owner incomplete window");nlohmann::json spans=nlohmann::json::array();for(int k=0;k<16;++k)spans.push_back({{"stage",k},{"start_ms",p.gpu[2*k]},{"end_ms",p.gpu[2*k+1]},{"stream_ms",p.gpu[2*k+1]-p.gpu[2*k]},{"host_wall_ms",1000*(p.hw[2*k+1]-p.hw[2*k])},{"thread_cpu_ms",1000*(p.tc[2*k+1]-p.tc[2*k])}});rows.push_back({{"device",dev},{"layer",l},{"owner",reinterpret_cast<uintptr_t>(p.owner)},{"stream",reinterpret_cast<uintptr_t>(p.stream)},{"markers",32},{"event_create_before_device",p.create_before},{"event_create_during_device",p.create_during},{"event_query_before_device",p.query_before},{"event_query_during_device",p.query_during},{"drain_host_ms",1000*p.drain},{"spans",spans}});}window.store(0);return nlohmann::json{{"schema",1},{"window",w},{"rows",rows}}.dump();}
}
